def build(p):
    import cadquery as cq
    out = None
    for a in (0, 90, 180, 270):
        ra = math.radians(a)
        x, z = (p['R_station'] - p['e_head']) * math.cos(ra), -(p['R_station'] - p['e_head']) * math.sin(ra)
        r = cq.Workplane("XZ").circle(p['ring_id'] / 2 + p['ring_w']).circle(p['ring_id'] / 2).extrude(-p['ring_h']).translate((x, p['ring_h'], z))
        out = r if out is None else out.union(r)
    return out
